function parseIp(ip){var p=String(ip).trim().split('.');if(p.length!==4)return null;var o=[];for(var i=0;i<4;i++){var x=parseInt(p[i],10);if(isNaN(x)||x<0||x>255)return null;o.push(x);}return o;}
function toDecimal(o){return ((o[0]<<24)|(o[1]<<16)|(o[2]<<8)|o[3])>>>0;}
function intToIp(n){n=n>>>0;return [(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255];}
function count(s,e){var a=parseIp(s),b=parseIp(e);if(!a||!b)return null;var da=toDecimal(a),db=toDecimal(b);if(db<da)return null;return db-da+1;}
function list(s,e,limit){limit=limit||256;var a=parseIp(s),b=parseIp(e);if(!a||!b)return null;var da=toDecimal(a),db=toDecimal(b);if(db<da)return null;var n=db-da+1;if(n>limit)return {truncated:true,total:n,items:[]};var items=[];for(var i=0;i<n;i++)items.push(intToIp((da+i)>>>0).join('.'));return {truncated:false,total:n,items:items};}
function rangeInfo(s,e){var c=count(s,e);if(c===null)return null;return {start:s,end:e,count:c};}
var EXPORTS={parseIp:parseIp,toDecimal:toDecimal,intToIp:intToIp,count:count,list:list,rangeInfo:rangeInfo};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
